import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ChartTypeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property chart type of observed panel ")
  void test_chart_type_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ChartTypeVO.tryFrom(null));
    Assertions.assertEquals("one", ChartTypeVO.from("one").getChartType());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ChartTypeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ChartTypeVO.from("one").toString());
  }
}
